INSERT INTO `courses` (`id`, `name`, `slug`, `description`, `long_description`, `thumbnail`, `banner_image`, `instructor_name`, `instructor_title`, `instructor_image`, `instructor_detail`, `duration`, `start_date`, `price`, `delivery`, `mode`, `language`, `skill_level`, `category`, `certification`, `requirements`, `curriculum`, `status`, `created_at`, `sort_order`) VALUES
('1', 'Six Sigma: Total Quality Applications', 'six-sigma-total-quality-applications', 'Determine the relationship of basic statistics to Six Sigma and learn about the Six Sigma business case, including strategic planning, the voice of the customer (VOC), quality function deployment (QFD), benchmarking, and financial investment methods. In this course, you will learn more than 25 tools and methods relate to the DMAIC (define, measure, analyze, improve, and control) model.', 'Determine the relationship of basic statistics to Six Sigma and learn about the Six Sigma business case, including strategic planning, the voice of the customer (VOC), quality function deployment (QFD), benchmarking, and financial investment methods. In this course, you will learn more than 25 tools and methods relate to the DMAIC (define, measure, analyze, improve, and control) model.', '/storage/courses/thumbnails/rB9PeE8IXEHOxY0LH0WwUNCsPvfSsPScZwI7kQAg.jpg', '/storage/courses/banners/LYjIFUq6UfrNkit4gpGjtDnzeOrtTRCZYnTI0njh.jpg', 'Tony Swaim', 'Senior Faculty', '', '<p>Tony Swaim has helped many clients, colleagues, and students reach their professional and personal goals. He has been an online instructor since 1998 and has taught at colleges and universities across the United States since 1981. His focus areas are project management, Six Sigma, and supply chain management. Tony manages a successful consulting firm, and his industry experience includes 20 years of supply chain management. He earned a Doctorate in Business Administration from Kennesaw State University and holds professional certifications in six disciplines, including the Project Management Professional (PMP)® certification from the Project Management Institute (PMI)® and Certified Six Sigma Black Belt (CSSBB)® from the American Society for Quality (ASQ)®.</p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Quality Management', 'pecp', '<p>Hardware Requirements:</p><ul><li>→There are no prerequisites other than basic computer skills to take this class.</li></ul><p><br>Software Requirements:</p><ul><li>→PC: Windows 8 or later.</li><li>→Mac: macOS 10.6 or later.</li><li>→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0"><strong>→Adobe Acrobat Reader</strong></a>.</li><li>→Software must be installed and fully operational before the course begins.</li></ul><p><br>Other Requirements:</p><ul><li>→Email capabilities and access to a personal email account.</li></ul><p><br>Instructional Material Requirements:</p><ul><li>→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p><strong>Lesson 1 – DMAIC and Basic Statistics</strong><br>In the first lesson, you’ll start off by investigating DMAIC, the most popular acronym within the Six Sigma body of knowledge. It stands for define, measure, analyze, improve, and control. Then, to set the stage for the remaining lessons, you’ll explore basic statistics. Since many of the Six Sigma methods and tools that will be discussed require that you have a basic knowledge of statistics, you’ll need to be well-prepared. The lesson will show you how to apply the measures of location—median, mode, mean—and the measures of dispersion—range, mean absolute deviation (MAD), variance, and standard deviation (SD).</p><p><br><strong>Lesson 2 – Six Sigma: The Business Case</strong><br>In this lesson, you’ll take a look at the business side of Six Sigma. The lesson will start off by discussing strategic planning—a concept that looks at internal strengths and weaknesses and external opportunities and threats. You’ll move on to two methods of identifying customer requirements—the voice of the customer (VOC) and quality function deployment (QFD). Next, you’ll explore benchmarking, a technique that helps you determine how your company matches up to the competition and industry standards. Finally, you’ll look at a few financial methods to help you keep track of key objectives.</p><p><br><strong>Lesson 3 – Define: The D of DMAIC</strong><br>You can’t improve something unless you first define it. To help identify what you’re dealing with, you’ll begin this lesson by reviewing the first element of the DMAIC model: define. You’ll move on and learn about the basic Six Sigma metrics—defects per unit (DPU), defects per million opportunities (DPMO), yield, and rolled throughput yield (RTY). Next, you’ll investigate a few team techniques to help define conditions and situations—brainstorming, brainwriting, nominal group technique (NGT), and affinity diagrams. You’ll finish up by seeing how Pareto charts and critical to quality (CTQ) relate to process and problem definition.</p><p><br><strong>Lesson 4 – Measure Part I: The M of DMAIC</strong><br>The next two lessons will tackle the measuring aspect of DMAIC. Along with defining a process, problem, or opportunity, you’ll need to measure things before you can improve them. You’ll learn about different types of data and gain an understanding of sampling by seeing how it’s used to analyze and observe populations. You’ll conclude the lesson by examining three graphical methods to measure a population: histograms, stem and leaf diagrams, and box and whisker plots.</p><p><br><strong>Lesson 5 – Measure Part II: The M of DMAIC</strong><br>As you continue to learn about the measure component of DMAIC, you’ll begin this lesson by looking at probability distributions, failure methods and effects analysis (FMEA), and physical measurement. The probability distributions that you’ll review (binomial, Poisson, and chi-square) are discrete. You’ll study their formulas and see how their distributions compare to the normal curve. FMEA is one of the most popular and effective Six Sigma tools. This lesson will help you learn about FMEA’s risk priority numbers (RPN) and also provide a form to help you use FMEA. You’ll wrap up the lesson by examining a few members of the physical measurement family—metrology, tensile strength, micrometers, and optical comparators.</p><p><br><strong>Lesson 6 – Analyze Part I: The A of DMAIC</strong><br>This lesson will present several tools that relate to the third component of DMAIC: analyze. The first order of business will be learning how to make sound decisions and assess risk. After that, you’ll look at tools to help you investigate the processes, problems, and opportunities you defined and measured in the earlier lessons. The lesson will teach you how to use regression analyses and cause and effect diagrams. You’ll also spend time on force field analysis, storyboards, decision trees, why-why diagrams, and finish up with checksheets and scatter diagrams.</p><p><br><strong>Lesson 7 – Analyze Part II: The A of DMAIC</strong><br>Are you familiar with the old saying, “A picture is worth a thousand words?” Since you’re going to be spending a large portion of the lesson learning about flowcharting, this quotation is very relevant. Flowcharts are a fine tool to define processes and analyze what’s taking place. You’ll look at the ins and outs and the subtleties of creating and using flowcharts. After that, you’ll jump back into the world of statistics and examine hypothesis testing and analysis of variance (ANOVA).</p><p><br><strong>Lesson 8 – Project Management Phases</strong><br>This lesson and the next one will discuss project management as an essential vehicle to help you achieve your Six Sigma plans. The lesson will begin by discussing the different phases of the project life cycle. Then, you’ll move on and examine deliverables. Since they represent what customers expect, you need to know how to create and manage them. The lesson will also define stakeholders and talk about what they expect. It will put special emphasis on the words “customers” and “stakeholders” to represent those inside and outside your organization.</p><p><br><strong>Lesson 9 – Project Definition and Scheduling</strong><br>Now that you have a good understanding of the different phases of a project and know all about deliverables, you’re ready to learn how to “scope” and schedule a project. Scoping refers to making sure that you set the original boundaries for your project. When you understand all the variables of your project and define the scope properly, your plan and the results that follow have a much better chance of meeting stakeholder expectations. This lesson will talk about what is arguably the most valuable item in your project management toolbox—a work breakdown structure (WBS). It will discuss two different versions of WBS and then you’ll look at ways to schedule your project.</p><p><strong>Lesson 10 – Improve: The I of DMAIC</strong><br>If you like playing games and solving puzzles, you’ll enjoy this lesson. It will address the “I element” (improve) of DMAIC by introducing design of experiments (DOE). Although DOE has been around since the 1920s, it’s taken a while for organizations to accept it. The lesson will begin with an overview and discuss what a design and an experiment are. You’ll learn about the history of DOE and its nature. Afterwards, the lesson will identify the principles of sound experimental design and help you work on three DOE problems: one factor at a time (OFAT), full factorial, and fractional factorial DOE.</p><p><br><strong>Lesson 11 – Control: The C of DMAIC</strong><br>This lesson will finish the examination of DMAIC by featuring the final letter—C for control. You’ll learn about three different tools to help you control your operations: run charts, control charts, and process capability. The lesson will discuss how to create run charts, give an overview of control charts, and show you how to create two different types of control charts. It will wrap things up by showing you how to use process capability.</p><p><br><strong>Lesson 12 – Thinking Lean</strong><br>You’ve just about completed all course requirements except for learning how to think lean—which is the topic of this lesson. Lean thinking means doing more with less. This is one way that companies succeed: providing more satisfaction and more quality with less effort and less frustration. Your focus on lean thinking will consist of eliminating waste, reducing lead time, and minimizing the impact of constraints.</p><p><br><strong>Prerequisites:</strong></p><p>Completion of Tony Swaim’s&nbsp;<i>Total Quality Fundamentals.</i></p>', 'published', '2025-10-27 22:35:05', 2),
('2', 'Fundamentals of Supervision and Management', 'fundamentals-of-supervision-and-management', 'This course is designed for anyone recently promoted to a supervisory or management position or wanting to learn how to become a more effective manager. You will learn the basics of business by learning the language of management. You will learn how to make a successful transition from employee to manager and how to manage your time so that you can deal with the demands of a managerial job.', 'This course is designed for anyone recently promoted to a supervisory or management position or wanting to learn how to become a more effective manager. You will learn the basics of business by learning the language of management. You will learn how to make a successful transition from employee to manager and how to manage your time so that you can deal with the demands of a managerial job.', '/storage/courses/thumbnails/gLwhgtL7JkB1vh4IlYkd6JsdvR2Mi3tCRRb7j6Rk.jpg', '/storage/courses/banners/o6A2GUxXmcBLqPhUkixtPN8XMU97HikfSr750tfh.jpg', 'Patricia Addesso', 'Senior Faculty', '', '<p>Patricia Addesso has worked for over 20 years in retail, academic and telecommunications organizations. She has a doctorate in Industrial/Organizational Psychology, and well-grounded in the theory of human behavior at work. In addition, she has held management positions in three companies, and thus “speaks the language” of upper management. This blend of the theoretical and the practical is the hallmark of her consulting style. Dr. Addesso’s specialty is organization development and team building. She has been involved in managing mergers, acquisitions, and other large-scale organizational changes, and is currently involved in projects such as strategic planning and personality assessments.</p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Executive & Leadership', 'pecp', '<p>Hardware Requirements:</p><ul><li>→There are no prerequisites other than basic computer skills to take this class.</li></ul><p><br>Software Requirements:</p><ul><li>→PC: Windows 8 or later.</li><li>→Mac: macOS 10.6 or later.</li><li>→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0"><strong>→Adobe Acrobat Reader</strong></a>.</li><li>→Software must be installed and fully operational before the course begins.</li></ul><p><br>Other Requirements:</p><ul><li>→Email capabilities and access to a personal email account.</li></ul><p><br>Instructional Material Requirements:</p><ul><li>→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p><strong>Lesson 1 – Introduction to Managerial Work</strong></p><p>How has management theory evolved over the last 100 years? This lesson will take you back to the older days of assembly lines and scientific management. You will learn how organizations are structured and describe managerial jobs in terms of the technical and managerial tasks that are performed.</p><p><br><strong>Lesson 2 – Making the Transition Into Management</strong></p><p>It’s time to identify the characteristics of a typical supervisor’s day and how they handle daily challenges. In this lesson, you will learn how to make the supervisor’s path smoother, such as empowerment and communication. How does one begin to think, act, and look like a manager?</p><p><br><strong>Lesson 3 – The Tasks of a Manager</strong></p><p>Is leadership distinct from management? Do you have what it takes to be a leader, or are you cut out to be just a manager? This lesson covers the evolution of leadership research and begin to discuss the fascinating field of motivation. Believe it or not, a good leader can build motivation right into the design of a job.</p><p><br><strong>Lesson 4 – Managing Tasks, Performance, and Time</strong></p><p>In this lesson, you will learn how a supervisor can handle the challenges of delegation, performance management, and time management. Once you understand the challenges of the typical day, you will understand the importance of time management to a supervisor.</p><p><br><strong>Lesson 5 – Introduction to Motivation</strong></p><p>It’s time to really dig into the topic dear to many managers’ hearts-motivation. This lesson clarifies what managers need to understand about human motivation and help you to understand the links between motivation and productivity.</p><p>Lesson 6 – The Best-Known Researchers in Motivation</p><p>Motivational theories are great as long as they truly help you to manage people at work every day. This lesson looks closely at four theories: Maslow’s hierarchy of needs, Herzberg’s two-factor theory of motivation, Alderfer’s theory on the three levels of human, and the three needs outlined by McClelland.</p><p><br><strong>Lesson 7 – Motivation Theories</strong></p><p>Do you believe that people naturally want to do a good job? Or are people lazy by nature and need to be watched? In this lesson, find out if you’re a Theory X or a Theory Y-type of manager. There are self-fulfilling prophecies to each of those beliefs.</p><p><br><strong>Lesson 8 – Understanding the Theories of Motivation</strong></p><p>This lesson defines two more very practical and influential motivational theories; equity theory and expectancy theory. This lesson wraps up the theoretical about the importance of creating a motivational environment.</p><p><br><strong>Lesson 9 – Introduction to Conflict Resolution and Problem-Solving</strong></p><p>Now comes the hard part: when real life doesn’t work out the way the theories said it should. What happens when conflict arises? This lesson explores conflict and conflict resolution. You will learn about specific techniques of negotiation, a particular type of conflict management.</p><p><br><strong>Lesson 10 – Models of Conflict Resolution and Problem-Solving</strong></p><p>This less about conflict and problem-solving in work groups? This lesson identifies means of solving conflict between groups. You will also learn a problem-solving model that is useful in work and in life.</p><p><br><strong>Lesson 11 – Working Through Problems</strong></p><p>This lesson explores the problem-solving model and talks about the importance of establishing objectives, generating alternatives, and choosing a solution.</p><p><br><strong>Lesson 12 – Implementing Solutions to Problems and Conflicts</strong></p><p>Your final lesson concludes the problem-solving model discussion and gives you the tools you need to carry the plan through to completion. You will explore the conflicts that may arise while solving problems and completing action plans.</p><p>&nbsp;</p><p><strong>Prerequisites:</strong></p><p>You must be proficient with basic algebra.</p>', 'published', '2025-10-28 00:01:39', 3),
('3', 'Project Management Fundamentals', 'project-management-fundamentals', 'This course Professional will help you master the essentials of project management. You will become an indispensable member of your project team by discovering and mastering the critical concepts you need to plan, implement, control and close any type of project.', 'This course Professional will help you master the essentials of project management. You will become an indispensable member of your project team by discovering and mastering the critical concepts you need to plan, implement, control and close any type of project.', '/storage/courses/thumbnails/SVahX3JklFfwZiXDcecZvsNYlQ7lLYeSTQZPZB5a.jpg', '/storage/courses/banners/vEh3WeJVIwmcW3Z4bOPxpdMhuXw47pXzuLlMtcOr.jpg', 'Tony Swaim', 'Senior Faculty', '', '<p>Tony Swaim has helped many clients, colleagues, and students reach their professional and personal goals. He has been an online instructor since 1998 and has taught at colleges and universities across the United States since 1981. His focus areas are project management, Six Sigma, and supply chain management. Tony manages a successful consulting firm, and his industry experience includes 20 years of supply chain management. He earned a Doctorate in Business Administration from Kennesaw State University and holds professional certifications in six disciplines, including the Project Management Professional (PMP)® certification from the Project Management Institute (PMI)® and Certified Six Sigma Black Belt (CSSBB)® from the American Society for Quality (ASQ)®.</p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Project Management', 'pecp', '<p>Hardware Requirements:</p><ul><li>→This course can be taken on either a PC, Mac, or Chromebook.</li></ul><p><br>Software Requirements:</p><ul><li>→PC: Windows 8 or later.</li><li>→Mac: macOS 10.6 or later.</li><li>→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0"><strong>→Adobe Acrobat Reader</strong></a>.</li><li>→Software must be installed and fully operational before the course begins.</li></ul><p><br>Other Requirements:</p><ul><li>→Email capabilities and access to a personal email account.</li></ul><p><br>Instructional Material Requirements:</p><ul><li>→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p><strong>Lesson 1 – Project Management Overview</strong><br>In our first lesson, you’ll learn why project management is necessary and find out how to differentiate projects from programs and tasks. When you finish with this lesson, you’ll understand the temporary and unique nature of projects and discover why scoping a project is a critical activity. This lesson will also provide pathways for a career in project management using guidelines from the Project Management Institute (PMI).</p><p><br><strong>Lesson 2 – The Power of Planning</strong><br>In this lesson, you will learn how planning represents a key factor in helping you develop your project plan. We’ll start off the lesson by discussing the nature of planning and discovering the benefits of planning. Next, we will move on to examine the various planning elements and identify the planning process. Then, we’ll explore two planning constraints: the triple constraint and the limiting factor. We’ll finish Lesson 2 by discussing how contingency planning can be beneficial, recognizing the power of the plan-do-check-act (PDCA) concept, and seeing how estimating is such an essential component of planning.</p><p><br><strong>Lesson 3 – The Power of Control</strong><br>We’ll start off this lesson with an overview of the control process, and we’ll review the reactions that many people have to it. You’ll discover the characteristics and goals of effective control systems and be able to identify the benefits of control. You’ll learn the prerequisites to use control, find out how to use steps of the control process, and identify problems with using control. You’ll also discover the various types of control techniques.</p><p><br><strong>Lesson 4 – The Project Manager and the Project Team</strong><br>This lesson may be the most important one in the course: A highly functional project team and an excellent project manager are critical success factors for any project. In this lesson, you’ll learn about a project manager’s roles and responsibilities, and also required skills and competencies. To support your project manager, you’ll discover the characteristics of a team, see how a team comes together, and find out how to use effective team building activities. Finally, we’ll discuss a few project challenges that teams may face.</p><p><br><strong>Lesson 5 – Stakeholder Interactions and Expectations</strong><br>In this lesson, we’ll discuss two different sides (deliverables and stakeholders) of the same coin. You’ll learn about the concept of deliverables, identify how deliverables are prone to change, and examine the deliverables chain. You’ll see how Quality Function Deployment (QFD) is a wonderful tool to identify and satisfy stakeholders. Also, you’ll learn how important it is to recognize and meet stakeholder requirements and how to minimize stakeholder conflict. You’ll spend time learning the ins and outs of communication and change management. Lastly, you’ll discover how you can use brainstorming and brainwriting, and describe the nominal group technique and affinity diagrams to help you create innovative project management ideas.</p><p><br><strong>Lesson 6 – Project Management Soft Skills</strong><br>This lesson focuses on the “soft skills” (activities related to interpersonal engagement) that you will certainly be able to apply in your future projects. You will get an overview of decision making, the behavioral aspects, and barriers that exist that influence decisions. A logical extension of decision-making is problem solving. You’ll learn about root cause analysis, a problem-solving model, cost benefit analysis, and decision trees. You’ll also get an introduction about organizational politics and examine the various political tactics. Then, you’ll finish the lesson by exploring conflict management and how to improve your negotiation skills.</p><p><br><strong>Lesson 7 – Project Cost Management</strong><br>This lesson focuses on the various elements of project cost management. You’ll start off by learning about several classification of costs. Then you’ll discover the elements of project budgeting including bottom-up and top-down budgeting, the S-curve, and an assumption log. Next, you’ll see how change requests and a change control board (CCB) assist with project cost control. You’ll move on to explore activity-based costing (ABC) and learn how a focus on cost drivers is superior to traditional approaches. Finally, you’ll examine variance analysis and earned value performance management (EVPM) as ways to help keep your project costs at or below budget.</p><p><br><strong>Lesson 8 – The Project Plan (Part 1)</strong><br>In this lesson, you’ll learn how to develop the first part of your project plan. You’ll start off by learning about the influence of external and internal environmental factors. Then you’ll discover the importance of a project’s strategic fit, structures used for project organization, and examine project selection criteria and models. Next, you’ll learn about the project planning hierarchy and see how effective development of a project’s statement of work (SOW), the project charter, the work breakdown structure (WBS), and the project schedule significantly increase the probability of having a successful project.</p><p><br><strong>Lesson 9 – The Project Plan (Part 2)</strong><br>This lesson is all about supporting plans for your project. You’ll start off by reading about the role of human resource, supply management, interface, and configuration management plans. Then, we’ll devote some time to discuss quality and how to implement a project quality plan. Next, we’ll explore cost management, risk management, and reporting plans. Finally, you’ll discover the ins and outs of project management software and determine the requirements for successful implementation.</p><p><br><strong>Lesson 10 – Project Implementation</strong><br>In this lesson, we’ll expand upon the fundamental elements so you can successfully implement your project plan. We’ll start off by describing the elements of a successful project. This will help you determine if your project is headed in the right direction. Next, you’ll discover why it’s beneficial to implement a pilot before launching your project. Then, you’ll see why it’s important to review work packages and establish project accounts. We’ll move on to examine what takes place with a project kick-off meeting. Finally, you’ll finish the lesson by exploring the interpersonal aspects of a project and discover how to keep your project moving in the right direction.</p><p><br><strong>Lesson 11 – Project Control</strong><br>Project control is the most important activity for your project. Regardless of how much time and effort you invest into your project plan, it’s likely that your actual results will differ from what you expect. If you don’t effectively control your project, the chances of meeting your project objectives are very slim. In this lesson, we’ll expand on what we discussed earlier in the course. We’ll start off by describing the principles of project control. Next, you’ll discover the nature of project performance measurements and move on to discuss project reporting and the frequency and responsibility for project control. Then, you’ll see what is involved with project progress monitoring before moving on to examine earned value performance management (EVPM) and identify its benefits. Finally, you’ll finish the lesson by exploring the nature of a project audit.</p><p><br><strong>Lesson 12 – Project Closure</strong><br>In our final lesson, we will talk about what happens at the end of a project. We’ll start off by describing the importance and value of project closure. Next, we’ll identify the reasons why project closure is skipped, and discuss a process plan for project closure. Then, we will move on to discuss runaway projects and the reasons why project fail. Finally, you’ll finish the lesson by discussing how to deal with premature project termination.</p><p><br><strong>Prerequisites:</strong></p><p>There are no prerequisites to take this course.</p>', 'published', '2025-10-28 00:04:53', 4),
('4', 'Introduction to Artificial Intelligence', 'introduction-to-artificial-intelligence', 'This course will introduce you to various forms of artificial intelligence (AI) and how we interact with AI as consumers in applications like chatbots and recommendation engines. You’ll see how AI provides analytics in business and consider industries that may be transformed or even disrupted by AI implementations.&nbsp;', 'This course will introduce you to various forms of artificial intelligence (AI) and how we interact with AI as consumers in applications like chatbots and recommendation engines. You’ll see how AI provides analytics in business and consider industries that may be transformed or even disrupted by AI implementations.&nbsp;', '/storage/courses/thumbnails/UEEbrsfriqS1akGt3UxsKsugry0Aj2ubcShJN7fQ.jpg', '/storage/courses/banners/c5ZbhucO30heJXlmSmuMVvt3rWeN8Ih0o2Q611Kv.jpg', 'David Iseminger', 'Senior Faculty', '', '<p>David Iseminger is an author and technology veteran with expertise in computing, networking, wireless and cloud technologies, data and analytics, artificial intelligence, and blockchain. While with Microsoft, David worked on early versions of Windows and its core networking infrastructure, transmission protocols, security, data visualizations, and multiple emerging cloud technologies. David is passionate about education, serving as a School Board director for over ten years, advocating at state and federal levels for increased learning standards, and has taught over 40,000 students through multiple technology courses. He has an awarded patent in Artificial Intelligence (AI) object detection and social posting methodologies. He is the founder and CEO of the blockchain company that created IronWeave, the unlimited scale blockchain platform, based on his patent-pending blockchain innovations and inventions</p><p><br><strong>Instructor Interaction</strong>: The instructor looks forward to interacting with learners in the online moderated discussion area to share their expertise and answer any questions you may have on the course content.</p>', '6 weeks', 'Rolling Admission', 350.00, 'online', 'Instructor-led', 'English', 'intermediate', 'Artificial Intelligence', 'pecp', '<p>Hardware Requirements:</p><ul><li>→This course can be taken on either a PC, Mac, or Chromebook.</li></ul><p><br>Software Requirements:</p><ul><li>→PC: Windows 8 or later.</li><li>→Mac: macOS 10.6 or later.</li><li>→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0"><strong>→Adobe Acrobat Reader</strong></a>.</li><li>→Software must be installed and fully operational before the course begins.</li></ul><p><br>Other Requirements:</p><ul><li>→Email capabilities and access to a personal email account.</li></ul><p><br>Instructional Material Requirements:</p><ul><li>→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p><strong>Lesson 1 – Introduction to Artificial Intelligence</strong></p><p>In this lesson, you will gain a clear understanding of what artificial intelligence is and its three forms—artificial narrow intelligence, artificial general intelligence, and artificial superintelligence. You’ll also see how AI is already part of our everyday lives, sometimes in ways, you may not even realize, and differentiate real-world and science-fiction AI.</p><p><br><strong>Lesson 2 – Artificial Intelligence in Business Today</strong></p><p>Now you will take a closer look at how we interact with AI as consumers in both pre-and post-purchase applications such as chatbots, recommendation engines, virtual reality, and shopping assistants. You’ll see how other AI applications can gather business-related data and use it to inform decisions within an organization, yielding business forecasting, and analytics. Finally, we’ll consider industries that may be transformed or even disrupted by AI implementations, such as healthcare and the financial and transportation sectors.</p><p><br><strong>Lesson 3 – Machine Learning</strong></p><p>This lesson delves into machine learning—how computers can “learn” by mapping input to output using complex mathematical and statistical models. Suitable algorithms plus useful training data can enable computers to improve their production over time, effectively learning as humans do. With just a little math, you’ll find out about supervised learning, including regression and classification, unsupervised learning, and reinforcement learning as they apply to computers. You will understand the importance of useful data in getting good results and how programmers avoid algorithmic bias.</p><p><br><strong>Lesson 4 – Neural Networks and Deep Learning</strong></p><p>In this deeper dive into how AI works, you’ll learn about artificial neural networks—basically computational models that loosely replicate the biological brain structure. You’ll see how an artificial neuron mimics a biological one and understands the specific training processes with a little more math. Then, you’ll examine deep learning, a specialized subset of machine learning, including convolutional neural networks, recurrent neural networks, and long short-term memory.</p><p><br><strong>Lesson 5 – Computer Vision</strong></p><p>Computer vision is a subset of artificial intelligence focusing on how computers can extract useful information from digital images or videos—easy for us, hard for them. You’ll learn about how computers store and interpret images, along with some of the most advanced AI applications involving facial and object detection and recognition, autonomous vehicles, and triage and early diagnosis in healthcare.</p><p><br><strong>Lesson 6 – Natural Language Processing</strong></p><p>You’ve probably seen natural language processing in action on your phone or digital home assistants such as Alexa, Google, or Siri. In this lesson, you’ll consider the intricate steps the computer must execute to understand and then carry out your commands, converting words into machine-usable numbers using natural language processing techniques and back into words using natural language generation. You’ll get a look at exactly how processes such as one-hot encoding, bag-of-words, term frequency, inverse document frequency, and word embedding work, as well as some applications of NLP in businesses today, including sentiment analysis and AI-powered surveys.</p><p><br><strong>Lesson 7 – Time Series Forecasting</strong></p><p>One beneficial application of AI is in forecasting. In this lesson, you will learn about time series analysis, which attempts to find the patterns in data. The pattern components are the trend, seasonality, cyclic patterns, and randomness (noise). Time series forecasting can involve univariate analysis (a single variable changing over time) or multivariate analysis. Many industries use time-series data analysis and forecastings, such as healthcare, sales, and weather prediction.</p><p><br><strong>Lesson 8 – Robotics</strong></p><p>Robots are a well-known AI application. Unlike humanoid robots from science fiction movies, many real-life robots around us today in factories, warehouses, agriculture, and even in homes don’t look much like people at all. You will learn about the kinds of tasks robots excel at, repetitive tasks with limited variability in a well-controlled environment. You will also learn about the challenges robotic projects face, such as high variability in the environment and high failure costs. Finally, you will see how robots are used today in two industries: logistics and agriculture.</p><p><br><strong>Lesson 9 – Implementing AI</strong></p><p>In this lesson, you will look at the AI development process and a typical AI project workflow, along with the low-level languages commonly used for AI programming. You will also learn about machine learning framework software and software suites that can help with AI development. In addition, you will discover pre-made AI services that you can buy ready to use (or nearly so) from vendors such as Amazon, IBM, Google, and Microsoft.</p><p><br><strong>Lesson 10 – AI and the Workforce</strong></p><p>AI has already started to affect employment, and its influence will continue to rise in the future. You will learn what job roles are involved in designing, developing, and deploying AI systems, including various types of engineers and data scientists, business analysts, and computing professionals. Thinking about what AI is good at (and not so good at), we will look at how jobs are being transformed and disrupted by AI and consider how several industries, and a variety of specific careers, might be affected.</p><p><br><strong>Lesson 11 – AI Ethics</strong></p><p>Given the power of artificial intelligence, it’s unsurprising that ethics is a big concern. You will learn how bias is an issue for human decision-making and decisions made by AI systems, some caused by programmers and some from training datasets. You will see how system engineers can develop AI systems in ways to make them more trustable by building in explainability and interpretability. You will also examine some of the ethical concerns with AI systems like facial recognition, such as loss of personal privacy and the potential for misuse.</p><p><br><strong>Lesson 12 – The Future of AI</strong></p><p>With your increased understanding of artificial intelligence and its capabilities, you will consider what the future will bring with AI. You will learn about areas that AI researchers are working on now, such as natural language processing and interacting with objects, and about neuromorphic computing and its relationship to neural network research. You will preview some up-and-coming technologies in storage and processing that will enable the next generation of AI applications and discover how AI is changing the workplace. Finally, you will look at some possible views of a future that features AI prominently and how AI developers seek to make AI systems safer by carefully creating incentive systems.</p><p><br><strong>Prerequisites:</strong></p><p>Basic computer skills and high school level mathematics are required.</p>', 'published', '2025-10-28 00:06:50', 5),
('5', 'Introduction to Business Analytics', 'introduction-to-business-analytics', 'Give yourself an employment advantage by developing analytical skills that are consistently in high demand. This course will teach you powerful quantitative methods that will have you making better, more informed, and more effective business decisions.', 'Give yourself an employment advantage by developing analytical skills that are consistently in high demand. This course will teach you powerful quantitative methods that will have you making better, more informed, and more effective business decisions.', '/storage/courses/thumbnails/GcCF3FJ92jM5kjN6COAsyDlVPGLNGHk2H4popO8y.jpg', '/storage/courses/banners/oOMHs3nBJWspMmWGet5sxJjBwNNaCw9ZEtndRKOj.jpg', 'Matt Crabtree', 'Senior Faculty', '', '<p><strong>Matt Crabtree,</strong>&nbsp;CFP ®, earned his Bachelor of Science in Business, Information Systems Management, in 1999, a mini MBA certificate from The School of Management at Yale University in 2004, a certificate in Financial Planning from Pepperdine University’s Graziadio School of Business in 2012 and has received the financial industry’s most rigorous and prestigious professional designation of Certified Financial Planner ™. After many years in project management, office management, and business sales, Matt began training individuals and organizations in areas of business finance, leadership development, successful negotiations, sales management, and customer service excellence. Matt has trained individuals and various units within the U.S. Department of Defense, as well as corporate organizations including IBM (technology), Accuray (healthcare-technology), and Gen-Probe (molecular diagnostics). Matt’s natural aptitude for explaining his material in an easy-to-understand and enjoyable manner allows each student to gain insights into areas that are often considered challenging.</p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Analytics & Data', 'pecp', '<p>Hardware Requirements:</p><ul><li>→This course can be taken on either a PC, Mac, or Chromebook.</li></ul><p><br>Software Requirements:</p><ul><li>→PC: Windows 8 or later.</li><li>→Mac: macOS 10.6 or later.</li><li>→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0"><strong>→Adobe Acrobat Reader</strong></a>.</li><li>→Software must be installed and fully operational before the course begins.</li></ul><p><br>Other Requirements:</p><ul><li>→Email capabilities and access to a personal email account.</li></ul><p><br>Instructional Material Requirements:</p><ul><li>→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p><strong>Lesson 1 – Problem Solving and Decision-Making</strong><br>Decision-making is one of the most important aspects of business, so you’ll start things off by exploring a variety of analytical approaches that you can use for making business decisions. You’ll also look at the basic steps involved in problem solving.</p><p><br><strong>Lesson 2 – Introduction to Probability</strong><br>This lesson will help you understand the probability of events. It will talk about basic probability concepts and how you can assign probabilities to experimental outcomes. You’ll also find out how to apply probability concepts to business situations.</p><p><br><strong>Lesson 3 – Introduction to Sampling and Surveys</strong><br>In this lesson, you’ll delve into the concepts of mean and standard deviation and how they’re used in business. You’ll also go over survey analysis, the various steps involved in doing a survey, and the most common errors that people make.</p><p><br><strong>Lesson 4 – Decision Analysis</strong><br>This lesson is all about the use of probability in decision-making. You’ll explore an analytical approach called Decision Analysis. You’ll learn how to structure a problem so that when you decide how to deal with it, you know what result to expect. The lesson will also talk about using an optimistic, conservative, and in-between approach when making decisions. Finally, you’ll examine the concept of Expected Value.</p><p><br><strong>Lesson 5 – Utility and Decision-Making</strong><br>What if the decision you want to make isn’t the most sensible one from a financial perspective? There are times when you need to base the worth of a decision on its value to you. An example of this would be deciding to buy a lottery ticket. Sometimes it’s appropriate to make business decisions this way. This lesson will talk about this approach and where the different decisions can lead.</p><p><br><strong>Lesson 6 – Forecasting</strong><br>All businesses need to forecast sales and expenses, and the forecasts need to be accurate. This lesson will cover forecasting as it’s done in business analysis. You’ll learn about the two types of forecasting: qualitative and quantitative.</p><p><br><strong>Lesson 7 – The Modeling Process</strong><br>In this lesson, you’ll discover modeling, which is the application of mathematical constructs to decision making. You’ll explore simple, intermediate, and complex types of models and discuss the two approaches to model development: reductionist and holistic.</p><p><br><strong>Lesson 8 – Modeling in a Corporate Environment</strong><br>This lesson is about how models are developed within a business organization. It will talk about what needs to be done and who needs to do it in order to make the modeling effort a success. You’ll explore the respective roles of the analyst (modeler) and the client for whom the model is being developed.</p><p><br><strong>Lesson 9 – Financial Analysis</strong><br>The most widely used type of business analysis is financial analysis. This probably doesn’t surprise you too much since the point of any business is to make a profit. In this lesson, you’ll look at financial analysis and how it differs from accounting. The lesson will discuss cost estimates and various types of business costs. You’ll get familiar with the concepts of break-even analysis and cost/benefit analysis, both of which play a vital role in business analysis.</p><p><br><strong>Lesson 10 – Project Management PERT/CPM</strong><br>The techniques of PERT (Program Evaluation and Review Technique) and CPM (Critical Path Method) have proven to be extremely valuable to project managers. This lesson will explain the basics of PERT/CPM and how to utilize these techniques in your work. You’ll meet a simple technique called a Gantt chart, which works quite well for planning a simple project with a relatively small number of tasks.</p><p><br><strong>Lesson 11 – Computer Simulation and Risk Analysis</strong><br>Risk is a part of any business situation, which makes it something you need to consider when you do business analysis. Simulation is an excellent method of performing risk analysis, so this lesson will cover step-by-step procedures for creating and using a simulation model.</p><p><br><strong>Lesson 12 – Computer-Based Information Systems</strong><br>In the final lesson, you’ll look at computer-based information systems. This includes such areas as Decision Support Systems, Optimization Analysis, and Knowledge-Based Systems. You’ll learn what each of these areas constitutes and examine many business applications of each.</p><p><br><strong>Prerequisites:</strong></p><p>You must be proficient with basic algebra.</p>', 'published', '2025-10-28 00:11:10', 1);
INSERT INTO `courses` (`id`, `name`, `slug`, `description`, `long_description`, `thumbnail`, `banner_image`, `instructor_name`, `instructor_title`, `instructor_image`, `instructor_detail`, `duration`, `start_date`, `price`, `delivery`, `mode`, `language`, `skill_level`, `category`, `certification`, `requirements`, `curriculum`, `status`, `created_at`, `sort_order`) VALUES
('course-1788413059055-7d47f17d', 'Creating Web Pages', 'creating-web-pages', '<blockquote style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Learn the basics of HTML as you design, create, and post your very own website. This course will help you plan the content, structure, and layout of your website, create neatly formatted text, build links, and add color, graphics, and tables, as well as understand no-cost web marketing strategies and SEO.</blockquote>', '<blockquote style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Learn the basics of HTML as you design, create, and post your very own website. This course will help you plan the content, structure, and layout of your website, create neatly formatted text, build links, and add color, graphics, and tables, as well as understand no-cost web marketing strategies and SEO.</blockquote>', '/uploads/webapge-1788424882397.png', '/uploads/CREATING_WEB_PAGES-1788424886097.png', 'Alan Simpson', 'Faculty Lead', '', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Alan Simpson</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Alan Simpson is an award-winning author with over 100 published books on computers, technology, and the internet, translated into more than a dozen languages. With extensive experience across nearly every aspect of the computer industry—including web development, operating systems, programming, networking, and security—he is widely regarded as a leading expert in the field.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Alan’s journey in tech began in the 1980s as an author, teacher, consultant, and software developer. His work in app development and web design sparked a deep interest in cybersecurity. This passion led him to pursue formal studies, and in 2007, he earned his Security+ certification from CompTIA, demonstrating his broad knowledge of the computer security field. The insights he shares in his courses reflect his years of experience and his commitment to building safe, secure applications and websites.</p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Web Development', 'PECP', '<p style="border-color: oklch(0.9 0.008 240);"><b>Hardware Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→This course can be taken on either a PC, Mac, or Chromebook.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Software Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→PC: Windows 8 or later.</li><li style="border-color: oklch(0.9 0.008 240);">→Mac: macOS 10.6 or later.</li><li style="border-color: oklch(0.9 0.008 240);">→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li style="border-color: oklch(0.9 0.008 240);"><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0" style="border-color: oklch(0.9 0.008 240);"><span style="border-color: oklch(0.9 0.008 240); font-weight: bolder;">→Adobe Acrobat Reader</span></a>.</li><li style="border-color: oklch(0.9 0.008 240);">→Software must be installed and fully operational before the course begins.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Other Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→Email capabilities and access to a personal email account.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Instructional Material Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 1 – Getting Started</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Get started by learning where the web is and how it works. In this lesson, you will learn some important concepts and terminology, and hopefully clear up some buzzwords you may have heard but not quite understood. Then, get started creating your first website.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 2 – Create Your First Web Page</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">In this lesson, you’ll create your first web page. You’ll learn how to add tags and content to your page, view your page in a browser, reopen it in an editor to make additions and changes, save those changes, and then view the updated page in a web browser. These skills will apply to every web page you ever create, and they’ll get you started on creating any page you can imagine</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 3 – Formatting Text</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">In this lesson, you’ll learn to beef up your pages with the design elements that you see on most websites. First, you will learn how to add headings, paragraphs, numbered lists, and bulleted lists to your pages, and the secrets to adding special characters like &amp;copy; and &amp;trade. Finally, you’ll discover how to add links to other peoples’ pages and to other pages within your own site.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 4 – Fun With Pictures</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Here’s your chance to add some visual excitement to your website! This lesson covers the basics about adding pictures to your web pages. You’ll discover how to download pictures right off the web, and you’ll also learn how to prepare and use your own pictures from a digital camera.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 5 – Creating Tables</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Tables are a terrific way to neatly organize content into rows and columns. You’ve no doubt seen tables used in other websites and countless other forms of publication. In this lesson, you’ll learn how to use HTML to create tables in your own web pages!</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 6 – HTML, XHTML, and CSS</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">If you’ve been involved in web development at all during the last 20 years, you may have heard about HTML, XHTML, HTML5, and CSS. If you’re new to all of this, it’s a confusing mess of alphabet soup. In this lesson, you’ll learn the who, how, what, when, where, and why of these technologies—and what you should use now so your website is in sync with current specs and future trends.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 7 – Getting Started With CSS</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Virtually all modern websites use CSS style rules for all their website styling. In this lesson, you’ll learn what a style rule is, and you’ll get some hands-on practice creating your own style rules. You’ll learn how to center and align pictures and text and discover the secrets to jazzing up your site with colors (and how to choose from the millions of color options available to you).</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 8 – Creating a Page Layout</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">This lesson will introduce you to more advanced HTML and CSS topics, including how to create a page layout with a navigation bar. You will learn how to create a page layout using div tags, how to style your page divisions, and some style rules.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 9 – Building Your Site</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Most websites consist of multiple pages with some common content on each page. This lesson will teach you to use a layout page as a template so you can build multipage websites more quickly. You’ll learn how to start with liquid layouts, how to design a layout from scratch, and how to use your layout to easily build additional pages. This will help you to develop more professional-looking pages using the same modern coding techniques that seasoned professionals use.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 10 – Getting Noticed</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">Getting a site on the Internet is one thing. Getting people to notice it is quite another. In this lesson, you’ll learn about Internet directory services, search engines, web-crawling infobots (not as creepy as they sound), and things you can do to make your own site stand out in the crowd!</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 11 – Publish Your Website</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">In this lesson, you’ll learn how to publish your website for the whole world to see. Best of all, you’ll learn how to keep your site on the Internet forever.</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 12 – Authoring Systems</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">In this lesson, you’ll learn about authoring systems like Dreamweaver and Expression Web, and how they can make web development quicker and easier. You’ll also learn a couple of ways to get an online presence without creating your own website!</p>', 'published', '2026-09-03 05:24:19', 6),
('course-1788413832348-df86fdfd', 'Introduction to C++ Programming', 'introduction-to-c-programming', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">This course will give you hands-on practice as you learn to program with C++. Whether you’re completely new to programming or you want to learn a new programming language, this course will teach you the fundamentals of C++.</p>', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;">This course will give you hands-on practice as you learn to program with C++. Whether you’re completely new to programming or you want to learn a new programming language, this course will teach you the fundamentals of C++.</p>', '/uploads/c___-1788424934840.png', '/uploads/c__-1788424931962.png', 'Jeffrey A. Kent', 'Faculty Lead', '', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Jeffrey A. Kent</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Jeffrey A. Kent is a Professor of Computer Science, teaching both traditional and online classes. He has taught a number of computer programming languages, including C, C++, Java, Visual Basic, and Assembly. He is the published author of several computer-programming books, including “Visual Basic 2005 Demystified” and “C++ Demystified.” He is also an attorney and has combined both careers by writing applications for law firms.</span></p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Programming & Software', 'PECP', '<p style="border-color: oklch(0.9 0.008 240);"><b>Hardware Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→This course can be taken on either a PC, Mac, or Chromebook.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Software Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→PC: Windows 8 or later.</li><li style="font-weight: 400; border-color: oklch(0.9 0.008 240);">→Mac: macOS 10.6 or later.</li><li style="font-weight: 400; border-color: oklch(0.9 0.008 240);">→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li style="font-weight: 400; border-color: oklch(0.9 0.008 240);"><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0" style="border-color: oklch(0.9 0.008 240);"><span style="border-color: oklch(0.9 0.008 240); font-weight: bolder;">→Adobe Acrobat Reader</span></a>.</li><li style="font-weight: 400; border-color: oklch(0.9 0.008 240);">→Software must be installed and fully operational before the course begins.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Other Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→Email capabilities and access to a personal email account.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Instructional Material Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240);"><li style="border-color: oklch(0.9 0.008 240);">→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 1 – Your First C++ Program</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In your first lesson, you’ll learn what a computer program is. What’s the best way to learn programming? You have to write programs, of course! Your first step toward writing your first program is to install VisualStudio. In this lesson, you’ll learn how to install Visual Studio on your computer and create your first program.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 2 – Understanding Your C++ Code and How to Fix Errors</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">You’ve created a working C++ application. In this lesson, you’ll find out what each line of C++ code means in your “Hello World!” program. You’ll also learn how this C++ code is translated to machine language that the computer understands and can execute as a running program. Finally, you’ll learn how to see and fix errors in your code.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 3 – Data Types and Computer Memory</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In this lesson, you’ll learn about the different areas of computer memory. You’ll find out about data types, which correspond to the different types of information a program uses, and then write a program that can determine the amount of computer memory used by different data types. This lesson also lays the foundation for variables, a very important concept in programming.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 4 – Storing Data in Variables</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In this lesson, you’ll learn how to create variables of different data types to store information. You’ll find out how to declare variables, which is the first step to using them. You’ll then learn how to assign values to variables, using both the assignment operator and cin. You’ll also access and output a variable’s value.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 5 – Letting the Computer Do the Math</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Computers can’t think for themselves—not yet anyway. But computers can calculate faster and more accurately than humans can. In this lesson, you’ll learn how to harness the computer’s calculating power with the C++ arithmetic operators.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 6 – Letting the User Choose</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Life involves choices, and so do computer programs. In this lesson, you’ll learn how to use the different C++ comparison operators and control structures so different blocks of code execute depending on the user’s choice.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 7 – Combining Choices</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Choices can be complicated. For example, you may want code to execute only if two choices are made, or if either of two choices are made. In this lesson, you’ll how to use nested control structures and the different C++ logical operators when more than one choice determines which block of code executes.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 8 – Repeating Code With Loops</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Your parents may have told you not to repeat yourself, but code often needs to repeat. In this lesson, you’ll learn how to use loops to make code repeat until a condition is met.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 9 – Using Arrays</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Often, you may need to store more than one item of information, such as multiple test scores. In this lesson, you’ll find out how to use arrays to store multiple items of information. Sure, you could also just use multiple variables, but with arrays, you also can harness the power of loops, which you learned about in the last lesson.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 10 – C Strings for Storing Text</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Not all information are numbers. You’ll often need to store text, such as names. In this lesson, you’ll discover how to use C strings to store non-numeric information in an array.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 11 – Functions for Dividing and Organizing Code</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">What if your favorite textbook was just one very long paragraph with no chapters or sections? The content would be the same, but it would be much more difficult to read and follow, wouldn’t it? Similarly, code, as it gets longer and more complicated, needs to be organized. In this lesson, you’ll learn how to use functions to divide tasks and organize your code.s.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 12 – Saving and Retrieving Data</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Microsoft Word wouldn’t be very useful if you couldn’t save your work and had to type it all over again each time you ran the program! Being able to save your work is important, but you also need to be able to load that saved work back into your program the next time you run it. In this lesson, you’ll learn how to use file input/output to store and retrieve information.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Prerequisites</b>:</p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">You must be proficient with basic algebra.</span></p>', 'published', '2026-09-03 05:37:12', 7),
('course-1788414064703-bfd12496', 'Introduction to Java Programming', 'introduction-to-java-programming', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Get comfortable programming with Java while gaining skills from an experienced Java programmer. This course provides you with easy-to-understand examples and plenty of skill-building exercises using the latest version of Java to give you confidence as you learn programming.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><br></p>', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Get comfortable programming with Java while gaining skills from an experienced Java programmer. This course provides you with easy-to-understand examples and plenty of skill-building exercises using the latest version of Java to give you confidence as you learn programming.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><br></p>', '/uploads/javaaaaa-1788424951152.png', '/uploads/java-1788424946862.png', 'Alan Simpson', 'Faculty Lead', '', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Alan Simpson</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Alan Simpson is an award-winning author with over 100 published books on computers, technology, and the internet, translated into more than a dozen languages. With extensive experience across nearly every aspect of the computer industry—including web development, operating systems, programming, networking, and security—he is widely regarded as a leading expert in the field.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Alan’s journey in tech began in the 1980s as an author, teacher, consultant, and software developer. His work in app development and web design sparked a deep interest in cybersecurity. This passion led him to pursue formal studies, and in 2007, he earned his Security+ certification from CompTIA, demonstrating his broad knowledge of the computer security field. The insights he shares in his courses reflect his years of experience and his commitment to building safe, secure applications and websites.</span></p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Programming & Software', 'PECP', '<p style="border-color: oklch(0.9 0.008 240);"><b>Hardware Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→This course can be taken on either a PC, Mac, or Chromebook.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Software Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→PC: Windows 8 or later.</li><li style="border-color: oklch(0.9 0.008 240);">→Mac: macOS 10.6 or later.</li><li style="border-color: oklch(0.9 0.008 240);">→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li style="border-color: oklch(0.9 0.008 240);"><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0" style="border-color: oklch(0.9 0.008 240);"><span style="border-color: oklch(0.9 0.008 240); font-weight: bolder;">→Adobe Acrobat Reader</span></a>.</li><li style="border-color: oklch(0.9 0.008 240);">→Software must be installed and fully operational before the course begins.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Other Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→Email capabilities and access to a personal email account.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Instructional Material Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 1 – Introducing Java</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Java is one of the most widely used programming languages in the world, on machines from microprocessors in DVRs and microwaves to supercomputers. This lesson will introduce you to computer programming in general and to Java in particular. First, you will be set up with the downloads and installations you will need for the rest of the course. Then, you will explore the process of editing, compiling, and running computer programs written in Java.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 2 – Writing Your First Java Program</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Now that you have the software downloaded and installed, you’re ready to start programming! It’s time to write your first Java program. Along the way, you will learn to create projects and classes in BlueJ. You will use the editor to enter your program, and you will find out more about how to compile it and run it.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 3 – Working With Java’s Primitive Data Types</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">This lesson is about Java’s primitive data types—the building blocks you need to use before you can build more complex types. First, you will learn how to use them in some simple programs and how they relate to each other. Beyond that, you will explore how to use these classes in the Java libraries.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 4 – Working With Objects</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">This lesson introduces classes and objects. You will revisit the HelloWorld application and rewrite it in Java’s OOP (object-oriented programming) structure. Whil</span></p>', 'published', '2026-09-03 05:41:04', 8);
INSERT INTO `courses` (`id`, `name`, `slug`, `description`, `long_description`, `thumbnail`, `banner_image`, `instructor_name`, `instructor_title`, `instructor_image`, `instructor_detail`, `duration`, `start_date`, `price`, `delivery`, `mode`, `language`, `skill_level`, `category`, `certification`, `requirements`, `curriculum`, `status`, `created_at`, `sort_order`) VALUES
('course-1788414333268-fd078c76', 'Growing Your Business with Digital Marketing', 'growing-your-business-with-digital-marketing', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In this hands-on course, you will discover proven methods for establishing an internet presence and building a brand identity. You will learn how to use digital marketing for small business growth, specifically how to incorporate search engine optimization (SEO), search engine marketing (SEM), advertising, email, social media, and more to develop an effective digital marketing plan even with little money to spend.</span></p>', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In this hands-on course, you will discover proven methods for establishing an internet presence and building a brand identity. You will learn how to use digital marketing for small business growth, specifically how to incorporate search engine optimization (SEO), search engine marketing (SEM), advertising, email, social media, and more to develop an effective digital marketing plan even with little money to spend.</span></p>', '/uploads/digitall-1788424965122.png', '/uploads/digital-1788424963182.png', 'Lisa Adams', 'Faculty Lead', '', '<p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lisa Adams</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Lisa Adams is a web development expert specializing in marketing, user experience, and e-commerce. With a wealth of experience building and maintaining websites, Lisa’s expertise extends beyond the digital realm. She is also a published author, showcasing her passion for writing and sharing her knowledge through engaging nonfiction books.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Lisa’s notable works include “S’mores: Gourmet Treats for Every Occasion,” published by Gibbs Smith, and “Why We Read What We Read: A Delightfully Opinionated Journey Through Contemporary Bestsellers,” published by Sourcebooks.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">Lisa’s accomplishments as a published author, combined with her expertise in web development, make her a well-rounded professional with a distinctive perspective. Her ability to effectively communicate ideas and share knowledge through her writing adds an extra layer of creativity and insight to her work in creating attractive, user-friendly websites for her clients and student</span></p>', '6 weeks', 'Rolling Admission', 250.00, 'online', 'Instructor-led', 'English', 'beginner', 'Digital Marketing', 'PECP', '<p style="border-color: oklch(0.9 0.008 240);"><b>Hardware Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→This course can be taken on either a PC, Mac, or Chromebook.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Software Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→PC: Windows 8 or later.</li><li style="border-color: oklch(0.9 0.008 240);">→Mac: macOS 10.6 or later.</li><li style="border-color: oklch(0.9 0.008 240);">→Browser: The latest version of Google Chrome or Mozilla Firefox are preferred. Microsoft Edge and Safari are also compatible.</li><li style="border-color: oklch(0.9 0.008 240);"><a href="https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fget.adobe.com%2Freader%2F&amp;data=05%7C02%7CMH190%40uscupstate.edu%7C72ce6c9349374f2e8d1508ddebe8d414%7C8cba7b629e8646c69b1b06504a61c72d%7C0%7C0%7C638926107727753120%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=L5osYCfz1hJprwGoLW9PSMbyS3n%2FuGprwL8QLwQ%2B2%2BI%3D&amp;reserved=0" style="border-color: oklch(0.9 0.008 240);"><span style="border-color: oklch(0.9 0.008 240); font-weight: bolder;">→Adobe Acrobat Reader</span></a>.</li><li style="border-color: oklch(0.9 0.008 240);">→Software must be installed and fully operational before the course begins.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Other Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→Email capabilities and access to a personal email account.</li></ul><p style="border-color: oklch(0.9 0.008 240);"><br style="border-color: oklch(0.9 0.008 240);"><b>Instructional Material Requirements:</b></p><ul style="border-color: oklch(0.9 0.008 240); font-weight: 400;"><li style="border-color: oklch(0.9 0.008 240);">→The instructional materials required for this course are included in enrollment and will be available online.</li></ul>', '<div><b>Lesson 1 – Understanding the Digital Ecosystem</b></div><div><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">There are millions of pages on the web, and more are added daily. With all these pages, how can you ensure that your website gets noticed? It isn’t easy. To increase traffic to your site, you need to learn all you can about digital marketing strategies and when to use each. In this lesson, we’ll start with a high-level view of these strategies with an introduction to the digital marketing ecosystem, several types of websites, and common business models.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 2 – Understanding Your Digital Footprint</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">To establish a web presence for your business, you’ll need to understand your goals, your customers’ needs, and your target audience. With this information, you can establish a market position that differentiates you from competitors and helps grow your digital footprint. We’ll discuss these topics and more in this lesson.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 3 – The Digital Customer Journey</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In this lesson, you’ll learn about the phases of the digital customer journey and how to create content and develop strategies for users during each phase. It’s essential to meet your prospective customers where they are, and this lesson will discuss ways to do just that.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 4 – Domain Names and Search Engines</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In this lesson, you’ll discover the importance of selecting your site’s domain name. You’ll also learn how search engines work. With this knowledge, you can make choices that help drive visitors to your website.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 5 – Website Optimization</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In this lesson, you’ll discover how to optimize your website so it ranks higher on search engine results pages. You’ll learn about keywords and coding elements to improve your site’s ranking and reach more visitors, as well as what backlinks are and how they can affect ranking.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 6 – Web Analytics</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">This lesson will explain how to find invaluable performance data about your website. The number of visitors, how long they stay, which pages they visit, and how they get to your site are just a few metrics you can evaluate to learn more about your audience and improve your site.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 7 – Paid Media</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">During this lesson, you’ll learn how to develop ads that inspire your target audience to take the action you want. You’ll understand how to advertise your website using search engine marketing (SEM), display advertising, video marketing, social media, and more..</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 8 – Email Marketing</b><br><span style="font-weight: normal;">Despite the growing number of junk email messages filling inboxes, email is still a thriving medium. So, it’s important to understand how to use email to keep current customers and acquire new ones. In this lesson, we’ll examine how you can use email to promote your business.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 9 – Creating Engagement Through Content</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">If you want visitors to spend more than a few seconds on your website, you’ll need to make it interesting, entertaining, and informative. Stickiness is the factor that causes visitors to spend more time at your site. In this lesson, you’ll learn how to use content such as blogs and syndicated content to make your website more engaging and increase stickiness.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 10 – Creating Engagement Through Community</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In the previous lesson, you learned to build site stickiness through content. In this lesson, you’ll learn to build site stickiness through social media. You’ll also become acquainted with synchronous and asynchronous tools you can use to develop a social media community experience for your visitors.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 11 – Selling Products Using E-Commerce</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">The last element you can use to build site stickiness is commerce, or, in this case, e-commerce. In this lesson, you’ll learn how to use e-commerce to engage visitors on your site and encourage them to return more often. You’ll become acquainted with technology you can use to create an online store, including shopping cart software and online payment systems.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Lesson 12 – Completing Your Digital Marketing Plan</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">In our final lesson, you’ll have the opportunity to compile all the information you gathered during this course to create your digital marketing plan. To help with this effort, you will download a checklist, calendar, and budget worksheet to walk you through the process of completing and implementing your plan.</span></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><b>Prerequisites:</b></p><p class="wp-block-paragraph" style="margin-bottom: 1rem; line-height: 30px; padding-bottom: 0.75rem; margin-block: 0px; max-width: 1248px; margin-left: auto !important; margin-right: auto !important;"><span style="font-weight: normal;">You must be proficient with basic algebra.</span></p></div>', 'published', '2026-09-03 05:45:33', 9);

